import java.util.*;

public class PairSumFinder {
    public static void main(String[] args) {
        // Example usage
        int[] array = {1, 2, 3, 4, 5};
        int targetSum = 5;
        findPairsWithSum(array, targetSum);
    }

    public static void findPairsWithSum(int[] array, int targetSum) {
        // Handle null or empty array
        if (array == null || array.length == 0) {
            System.out.println("Input array is empty or null.");
            return;
        }

        Set<Integer> seen = new HashSet<>();
        List<int[]> pairs = new ArrayList<>();
        Set<String> usedPairs = new HashSet<>();

        for (int i = 0; i < array.length; i++) {
            int current = array[i];
            int complement = targetSum - current;

            // Check if the complement exists in the set and hasn't been used
            if (seen.contains(complement) && !usedPairs.contains(complement + "," + current)) {
                // Add the pair to the list
                pairs.add(new int[]{current, complement});
                // Mark the pair as used
                usedPairs.add(current + "," + complement);
            } else {
                // Add the current number to the set
                seen.add(current);
            }
        }

        // Print the pairs
        if (pairs.isEmpty()) {
            System.out.println("No pairs found.");
        } else {
            System.out.println("Pairs found:");
            for (int[] pair : pairs) {
                System.out.println("(" + pair[0] + ", " + pair[1] + ")");
            }
        }
    }
}
